<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from "vue";
import {useAuth} from "@papilio/auth";
import {item,request,query,type Page,type CustomerTier,type LoyaltyPolicyRead,type LoyaltyPolicy} from "@papilio/api";
import Modal from "@papilio/ui/Modal.vue";
import {faNumber,toman} from "@papilio/ui";
const auth=useAuth(),rows=ref<CustomerTier[]>([]),page=ref(1),pages=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(""),notice=ref("");
const savedPolicy=ref<LoyaltyPolicyRead|null>(null),policyDraft=ref<LoyaltyPolicy|null>(null),overrideJson=ref("{}"),policyOpen=ref(false),tierOpen=ref(false),selected=ref<CustomerTier|null>(null);
const minimumPaymentToman=ref(0);
const draft=ref({code:"",title:"",minimum_bytes:0,discount_bps:0,is_enabled:true});let alive=true,version=0;
const booleans=[['enabled','Enable loyalty'],['renewal_tier_discount','Tier discounts on renewals'],['notify_tier_changes','Announce tier changes'],['notify_discounts','Announce applied discounts']] as const;
function fail(cause:unknown):void{error.value=cause instanceof Error?cause.message:"Could not complete this operation.";}
async function load():Promise<void>{const stamp=++version;loading.value=true;error.value="";try{const [tiers,policy]=await Promise.all([request<Page<CustomerTier>>(`/v1/admin/loyalty/tiers?${query({page:page.value})}`),item<LoyaltyPolicyRead>("/v1/admin/loyalty/policy")]);if(!alive||stamp!==version)return;rows.value=tiers.data;pages.value=tiers.meta.pager?.total_pages??1;total.value=tiers.meta.pager?.total_items??0;if(!policyOpen.value)savedPolicy.value=policy;}catch(cause){if(alive&&stamp===version)fail(cause);}finally{if(stamp===version)loading.value=false;}}
async function initialize():Promise<void>{busy.value=true;error.value="";try{await item<LoyaltyPolicyRead>("/v1/admin/loyalty/initialize","POST");notice.value="Missing configured tiers were added. Existing edits were preserved.";await load();}catch(cause){fail(cause);}finally{busy.value=false;}}
function edit(row:CustomerTier|null):void{selected.value=row;draft.value=row?{code:row.code,title:row.title,minimum_bytes:row.minimum_bytes,discount_bps:row.discount_bps,is_enabled:row.is_enabled}:{code:"",title:"",minimum_bytes:0,discount_bps:0,is_enabled:true};error.value="";tierOpen.value=true;}
async function saveTier():Promise<void>{busy.value=true;error.value="";try{if(!Number.isSafeInteger(draft.value.minimum_bytes)||!Number.isSafeInteger(draft.value.discount_bps))throw Error("Quota and basis points must be safe whole numbers.");await item<CustomerTier>(selected.value?`/v1/admin/loyalty/tiers/${selected.value.id}`:"/v1/admin/loyalty/tiers",selected.value?"PUT":"POST",{...draft.value,expected_revision:selected.value?.revision??null});tierOpen.value=false;await load();}catch(cause){fail(cause);}finally{busy.value=false;}}
function editPolicy():void{if(!savedPolicy.value)return;policyDraft.value={...savedPolicy.value.values,unlimited_plan_bytes:{...savedPolicy.value.values.unlimited_plan_bytes}};overrideJson.value=JSON.stringify(policyDraft.value.unlimited_plan_bytes,null,2);minimumPaymentToman.value=policyDraft.value.minimum_qualifying_rial/10;error.value="";policyOpen.value=true;}
async function savePolicy():Promise<void>{if(!policyDraft.value||!savedPolicy.value)return;busy.value=true;error.value="";try{const overrides:unknown=JSON.parse(overrideJson.value);if(!overrides||typeof overrides!=="object"||Array.isArray(overrides)||Object.entries(overrides).some(([id,value])=>!/^\d+$/.test(id)||Number(id)<=0||typeof value!=="number"||!Number.isSafeInteger(value)||value<0))throw Error("Plan overrides map positive plan IDs to non-negative whole bytes.");const result=await item<LoyaltyPolicyRead>("/v1/admin/loyalty/policy","PUT",{expected_revision:savedPolicy.value.revision,values:{...policyDraft.value,minimum_qualifying_rial:Math.round(minimumPaymentToman.value*10),unlimited_plan_bytes:overrides}});savedPolicy.value=result;policyOpen.value=false;notice.value="Loyalty rules saved. Completed purchase prices are preserved.";}catch(cause){fail(cause);}finally{busy.value=false;}}
onMounted(()=>void load());onBeforeUnmount(()=>{alive=false;version++;});
</script>
<template>
 <header class="page-head"><div><p class="eyebrow">COMMERCE</p><h1>Loyalty & discounts</h1><p class="subtitle">Purchased quota determines customer tiers. Rules apply when a purchase is charged.</p></div><div class="toolbar"><button v-if="auth.can('catalog','create')" class="btn secondary" :disabled="busy" @click="initialize">Seed missing tiers</button><button v-if="auth.can('catalog','create')" class="btn" @click="edit(null)">Create tier</button></div></header>
 <p v-if="error&&!tierOpen&&!policyOpen" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
 <section class="card card-pad"><div class="toolbar"><h2>Discount policy</h2><button class="btn secondary" :disabled="loading" @click="load">Refresh</button><button v-if="auth.can('catalog','update')&&savedPolicy" class="btn" @click="editPolicy">Edit policy</button></div><template v-if="savedPolicy"><p>{{savedPolicy.values.enabled?'Enabled':'Disabled'}} · Revision {{faNumber(savedPolicy.revision)}} · {{savedPolicy.values.tier_basis==='net_purchases'?'Net purchased quota after refunds':'Lifetime purchased quota'}}</p><p>First purchase: {{faNumber(savedPolicy.values.first_purchase_discount_bps/100)}}% · Maximum discount: {{faNumber(savedPolicy.values.maximum_discount_bps/100)}}% · Combination: {{savedPolicy.values.combination_mode}}</p><p>Unlimited plans: {{savedPolicy.values.unlimited_credit_mode==='exclude'?'No quota credit':faNumber(savedPolicy.values.unlimited_equivalent_bytes/1024**3)+' GiB equivalent'}} · Minimum qualifying payment: {{toman(savedPolicy.values.minimum_qualifying_rial)}}</p></template></section>
 <section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Tier</th><th>Minimum purchased quota</th><th>Discount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.title}}</strong><br/>{{row.code}}</td><td>{{faNumber(row.minimum_bytes/1024**3)}} GiB</td><td>{{faNumber(row.discount_bps/100)}}%</td><td><span class="badge" :class="row.is_enabled?'success':'warning'">{{row.is_enabled?'Enabled':'Disabled'}}</span></td><td><button v-if="auth.can('catalog','update')" class="btn small secondary" @click="edit(row)">Edit {{row.title}}</button></td></tr></tbody></table><p v-if="loading" class="empty">Loading tiers…</p><p v-else-if="!error&&!rows.length" class="empty">No tiers found. Seed configured tiers or create one.</p></div><div class="pager"><button :disabled="loading||page<=1" @click="page--;load()">‹</button><span>Page {{faNumber(page)}} · {{faNumber(total)}} tiers</span><button :disabled="loading||page>=pages" @click="page++;load()">›</button></div></section>
 <Modal v-model="tierOpen" :title="selected?'Edit '+selected.title:'Create customer tier'" :busy="busy"><form class="form-grid" @submit.prevent="saveTier"><p v-if="error" class="message error" role="alert">{{error}}</p><label class="field"><span>Code</span><input v-model="draft.code" required pattern="[a-z0-9_-]+" minlength="2" maxlength="32"/></label><label class="field"><span>Title</span><input v-model="draft.title" required minlength="2" maxlength="100"/></label><label class="field"><span>Minimum purchased quota (bytes)</span><input v-model.number="draft.minimum_bytes" type="number" min="0" step="1" required/></label><label class="field"><span>Discount (basis points; 100 = 1%)</span><input v-model.number="draft.discount_bps" type="number" min="0" max="10000" step="1" required/></label><label class="check-row"><input v-model="draft.is_enabled" type="checkbox"/>Enabled</label><p v-if="selected">Editing saved revision {{faNumber(selected.revision)}}. A conflicting write retains this draft.</p><button class="btn" :disabled="busy">Save tier</button></form></Modal>
 <Modal v-model="policyOpen" title="Loyalty and discount rules" :busy="busy" wide><form v-if="policyDraft" class="form-grid" @submit.prevent="savePolicy"><p v-if="error" class="message error" role="alert">{{error}}</p><p>Editing revision {{faNumber(savedPolicy?.revision??0)}}. Close and reopen after refreshing to review a conflict; failed values remain in this dialog.</p><div class="form-grid three"><label v-for="[field,label] in booleans" :key="field" class="check-row"><input v-model="policyDraft[field]" type="checkbox"/>{{label}}</label><label class="field"><span>Tier basis</span><select v-model="policyDraft.tier_basis"><option value="net_purchases">Net purchases after refunds</option><option value="lifetime_purchases">Lifetime purchases</option></select></label><label class="field"><span>Discount combination</span><select v-model="policyDraft.combination_mode"><option value="best">Best single discount</option><option value="additive">Add discounts</option><option value="sequential">Apply sequentially</option></select></label><label class="field"><span>First-purchase eligibility</span><select v-model="policyDraft.first_purchase_basis"><option value="net_purchases">Net purchases after refunds</option><option value="lifetime_purchases">No previous qualifying purchase, including refunded purchases</option></select></label><label class="field"><span>First-purchase discount (basis points)</span><input v-model.number="policyDraft.first_purchase_discount_bps" type="number" min="0" max="10000" required/></label><label class="field"><span>Maximum discount (basis points)</span><input v-model.number="policyDraft.maximum_discount_bps" type="number" min="0" max="10000" required/></label><label class="field"><span>Minimum qualifying payment (toman)</span><input v-model.number="minimumPaymentToman" type="number" min="0" step="0.1" required/></label><label class="field"><span>Unlimited quota credit</span><select v-model="policyDraft.unlimited_credit_mode"><option value="exclude">Exclude unlimited plans</option><option value="equivalent">Equivalent purchased quota</option></select></label><label class="field"><span>Default unlimited equivalent (bytes)</span><input v-model.number="policyDraft.unlimited_equivalent_bytes" type="number" min="0" step="1" required/></label></div><label class="field"><span>Unlimited plan equivalents: JSON of plan ID → bytes</span><textarea v-model="overrideJson" rows="5" spellcheck="false"/></label><p class="subtitle">Discounts round down to whole rial. Refunds reverse net quota credit once. First-purchase discounts do not repeat on automatic renewal.</p><button class="btn" :disabled="busy">Save policy</button></form></Modal>
</template>
